"""Test suite for django.forms.formsets module."""

from django.core.exceptions import ValidationError
from django.forms import Form, IntegerField, CharField
from django.forms.formsets import (
    BaseFormSet,
    ManagementForm,
    all_valid,
    formset_factory,
    DELETION_FIELD_NAME,
    ORDERING_FIELD_NAME,
    TOTAL_FORM_COUNT,
    INITIAL_FORM_COUNT,
    MIN_NUM_FORM_COUNT,
    MAX_NUM_FORM_COUNT,
)
from django.forms.utils import ErrorList
from django.test import SimpleTestCase


class TestForm(Form):
    """Simple form for testing formsets."""
    name = CharField()
    age = IntegerField(required=False)


# Create concrete formset classes using formset_factory
TestFormSet = formset_factory(TestForm)
TestFormSetWithExtra = formset_factory(TestForm, extra=2)
TestFormSetWithCanDelete = formset_factory(TestForm, can_delete=True)
TestFormSetWithCanOrder = formset_factory(TestForm, can_order=True)
TestFormSetWithMinNum = formset_factory(TestForm, min_num=3)
TestFormSetWithMaxNum = formset_factory(TestForm, max_num=5)
TestFormSetWithValidateMax = formset_factory(TestForm, validate_max=True)
TestFormSetWithValidateMin = formset_factory(TestForm, validate_min=True)
TestFormSetWithAbsoluteMax = formset_factory(TestForm, absolute_max=200)


class TestManagementForm(SimpleTestCase):
    """Tests for ManagementForm class."""

    def test_management_form_initialization(self):
        form = ManagementForm()
        self.assertIn('TOTAL_FORMS', form.fields)
        self.assertIn('INITIAL_FORMS', form.fields)
        self.assertIn('MIN_NUM_FORMS', form.fields)
        self.assertIn('MAX_NUM_FORMS', form.fields)

    def test_management_form_bound_with_data(self):
        data = {
            'TOTAL_FORMS': '2',
            'INITIAL_FORMS': '0',
        }
        form = ManagementForm(data=data)
        self.assertTrue(form.is_bound)
        self.assertTrue(form.is_valid())
        self.assertEqual(form.cleaned_data['TOTAL_FORMS'], 2)
        self.assertEqual(form.cleaned_data['INITIAL_FORMS'], 0)

    def test_management_form_clean_default_values(self):
        # When management form is invalid, defaults should be set
        form = ManagementForm(data={})
        form.full_clean()
        self.assertEqual(form.cleaned_data.get('TOTAL_FORMS'), 0)
        self.assertEqual(form.cleaned_data.get('INITIAL_FORMS'), 0)


