class TestAllValidFunction(SimpleTestCase):
    """Tests for all_valid function."""

    def test_all_valid_true(self):
        FormSet = formset_factory(TestForm)
        data1 = {'form-TOTAL_FORMS': '1', 'form-INITIAL_FORMS': '0', 'form-0-name': 'John'}
        data2 = {'form-TOTAL_FORMS': '1', 'form-INITIAL_FORMS': '0', 'form-0-name': 'Jane'}
        fs1 = FormSet(data=data1)
        fs2 = FormSet(data=data2)
        result = all_valid([fs1, fs2])
        self.assertTrue(result)

    def test_all_valid_false(self):
        FormSet = formset_factory(TestForm)
        data1 = {'form-TOTAL_FORMS': '1', 'form-INITIAL_FORMS': '0', 'form-0-name': 'John'}
        data2 = {'form-TOTAL_FORMS': '1', 'form-INITIAL_FORMS': '0', 'form-0-name': ''}
        fs1 = FormSet(data=data1)
        fs2 = FormSet(data=data2)
        result = all_valid([fs1, fs2])
        self.assertFalse(result)

    def test_all_valid_empty_list(self):
        result = all_valid([])
        self.assertTrue(result)


