class TestAdminSiteInit(SimpleTestCase):
    """Tests for AdminSite.__init__ method."""

    def test_init_default_name(self):
        admin_site = AdminSite()
        self.assertEqual(admin_site.name, 'admin')

    def test_init_custom_name(self):
        admin_site = AdminSite(name='custom_admin')
        self.assertEqual(admin_site.name, 'custom_admin')

    def test_init_registry_empty(self):
        admin_site = AdminSite()
        self.assertEqual(admin_site._registry, {})

    def test_init_actions_default(self):
        admin_site = AdminSite()
        self.assertIn('delete_selected', admin_site._actions)
        self.assertEqual(admin_site._actions['delete_selected'], actions.delete_selected)

    def test_init_global_actions_copy(self):
