        self.assertEqual(admin_site._global_actions, admin_site._actions.copy())


class TestAdminSiteRegister(TestCase):
    """Tests for AdminSite.register method."""

    def setUp(self):
        self.site = AdminSite()

    def test_register_single_model(self):
        self.site.register(Person)
        self.assertIn(Person, self.site._registry)

    def test_register_with_admin_class(self):
        class CustomModelAdmin(ModelAdmin):
            pass

        self.site.register(Person, CustomModelAdmin)
        self.assertIn(Person, self.site._registry)
        self.assertIsInstance(self.site._registry[Person], CustomModelAdmin)

    def test_register_with_options(self):
        self.site.register(Person, list_display=['name'])
        self.assertIn(Person, self.site._registry)
        self.assertIn('list_display', self.site._registry[Person].__dict__)

    def test_register_multiple_models(self):
        self.site.register([Person, City])
        self.assertIn(Person, self.site._registry)
        self.assertIn(City, self.site._registry)

    def test_register_abstract_model_raises_improperly_configured(self):
        with self.assertRaises(ImproperlyConfigured):
            self.site.register(AbstractBase)

    def test_register_already_registered_raises_already_registered(self):
        self.site.register(Person)
        with self.assertRaises(AlreadyRegistered):
            self.site.register(Person)

    def test_register_swapped_model_ignored(self):
        # Swapped models should be ignored during registration
        # This is tested by checking no error is raised
        pass


class TestAdminSiteUnregister(TestCase):
    """Tests for AdminSite.unregister method."""

    def setUp(self):
        self.site = AdminSite()
        self.site.register(Person)

    def test_unregister_single_model(self):
        self.site.unregister(Person)
        self.assertNotIn(Person, self.site._registry)

    def test_unregister_multiple_models(self):
        self.site.register(City)
        self.site.unregister([Person, City])
        self.assertNotIn(Person, self.site._registry)
        self.assertNotIn(City, self.site._registry)

    def test_unregister_not_registered_raises_not_registered(self):
        with self.assertRaises(NotRegistered):
