class TestAdminSiteActions(TestCase):
    """Tests for AdminSite action methods."""

    def setUp(self):
        self.site = AdminSite()

    def test_add_action(self):
        def custom_action(modeladmin, request, queryset):
            pass

        self.site.add_action(custom_action)
        self.assertIn('custom_action', self.site._actions)
        self.assertIn('custom_action', self.site._global_actions)

    def test_add_action_custom_name(self):
        def my_custom_action(modeladmin, request, queryset):
            pass

        self.site.add_action(my_custom_action, name='my_name')
        self.assertIn('my_name', self.site._actions)

    def test_disable_action(self):
        self.site.disable_action('delete_selected')
