"""Tests for django.utils.decorators module."""

from django.test import SimpleTestCase


class ClassOnlyMethodTests(SimpleTestCase):
    """Tests for the classonlymethod class."""

    def test_classonlymethod_available_on_class(self):
        """Test that classonlymethod is available on the class."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classonlymethod
            def cls_method(cls):
                return "class method"

        # Should work when called on the class
        result = TestClass.cls_method()
        self.assertEqual(result, "class method")

    def test_classonlymethod_raises_on_instance_access(self):
        """Test that classonlymethod raises AttributeError on instance access."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classonlymethod
            def cls_method(cls):
                return "class method"

        instance = TestClass()
        with self.assertRaises(AttributeError) as context:
            instance.cls_method()
        self.assertIn("This method is available only on the class", str(context.exception))


class MultiDecorateTests(SimpleTestCase):
    """Tests for the _multi_decorate function."""

    def test_multi_decorate_single_decorator(self):
        """Test _multi_decorate with a single decorator."""
        from django.utils.decorators import _multi_decorate

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class TestClass:
            def my_method(self):
                return "original"

        decorated = _multi_decorate(my_decorator, TestClass.my_method)
        instance = TestClass()
        result = decorated(instance)
        self.assertEqual(result, "original_decorated")

    def test_multi_decorate_multiple_decorators(self):
        """Test _multi_decorate with multiple decorators."""
        from django.utils.decorators import _multi_decorate

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d2"
            return wrapper

        class TestClass:
            def my_method(self):
                return "original"

        decorated = _multi_decorate([decorator1, decorator2], TestClass.my_method)
        instance = TestClass()
        result = decorated(instance)
        # Order is reversed due to how _multi_decorate applies decorators
        self.assertEqual(result, "original_d2_d1")

    def test_multi_decorate_preserves_attributes(self):
        """Test that _multi_decorate preserves function attributes."""
        from django.utils.decorators import _multi_decorate

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.custom_attr = "custom"
            return wrapper

        class TestClass:
            def my_method(self):
                return "original"

        decorated = _multi_decorate(my_decorator, TestClass.my_method)
        self.assertTrue(hasattr(decorated, 'custom_attr'))
        self.assertEqual(decorated.custom_attr, "custom")


class MethodDecoratorTests(SimpleTestCase):
    """Tests for the method_decorator function."""

    def test_method_decorator_on_function(self):
        """Test method_decorator applied to a function."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        # When decorating a function directly (not a method), 
        # method_decorator treats it as if it were a method
        # So we call it with a dummy self argument
        def my_function():
            return "original"

        wrapped_func = method_decorator(my_decorator)(my_function)

        result = wrapped_func(None)  # Pass None as 'self' since it's not really a method
        self.assertEqual(result, "original_decorated")

    def test_method_decorator_on_class_method(self):
        """Test method_decorator applied to a class method."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        @method_decorator(my_decorator, name='my_method')
        class TestClass:
            def my_method(self):
                return "original"

        instance = TestClass()
        result = instance.my_method()
        self.assertEqual(result, "original_decorated")

    def test_method_decorator_missing_name_raises_value_error(self):
        """Test that missing name argument raises ValueError."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        with self.assertRaises(ValueError) as context:
            @method_decorator(my_decorator)
            class TestClass:
                pass

        self.assertIn("The keyword argument `name` must be the name of a method", str(context.exception))

    def test_method_decorator_non_callable_raises_type_error(self):
        """Test that non-callable attribute raises TypeError."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        with self.assertRaises(TypeError) as context:
            @method_decorator(my_decorator, name='non_callable_attr')
            class TestClass:
                non_callable_attr = "not callable"

        self.assertIn("Cannot decorate", str(context.exception))

    def test_method_decorator_preserves_name(self):
        """Test that method_decorator preserves the original function name."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        @method_decorator(my_decorator, name='my_method')
        class TestClass:
            def my_method(self):
                return "original"

        self.assertEqual(TestClass.my_method.__name__, 'my_method')


