class EdgeCaseTests(SimpleTestCase):
    """Tests for edge cases and boundary conditions."""

    def test_method_decorator_empty_name_on_class(self):
        """Test method_decorator with empty name on class without method."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        with self.assertRaises(ValueError) as context:
            @method_decorator(my_decorator)
            class TestClass:
                pass

        self.assertIn("The keyword argument `name` must be the name of a method", str(context.exception))

    def test_method_decorator_iterable_decorator(self):
        """Test method_decorator with iterable decorator."""
        from django.utils.decorators import method_decorator

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d2"
            return wrapper

        @method_decorator([decorator1, decorator2], name='my_method')
        class TestClass:
            def my_method(self):
                return "original"

        instance = TestClass()
        result = instance.my_method()
        # Order is reversed due to how _multi_decorate applies decorators
        self.assertEqual(result, "original_d2_d1")

    def test_make_middleware_decorator_kwargs(self):
        """Test make_middleware_decorator with keyword arguments."""
        from django.utils.decorators import make_middleware_decorator

        class TestMiddleware:
            def __init__(self, get_response, timeout=30):
                self.get_response = get_response
                self.timeout = timeout

        decorator_factory = make_middleware_decorator(TestMiddleware)
        decorator = decorator_factory(timeout=60)
        self.assertTrue(callable(decorator))

    def test_classonlymethod_with_inheritance(self):
        """Test classonlymethod with inheritance."""
        from django.utils.decorators import classonlymethod

        class ParentClass:
            @classonlymethod
            def parent_method(cls):
                return "parent"

        class ChildClass(ParentClass):
            pass

        # Should work on child class too
        result = ChildClass.parent_method()
        self.assertEqual(result, "parent")

        # Should still fail on instance
        instance = ChildClass()
        with self.assertRaises(AttributeError):
            instance.parent_method()

    def test_multi_decorate_with_list(self):
        """Test _multi_decorate with a list of decorators."""
        from django.utils.decorators import _multi_decorate

        def decorator_factory(n):
            def decorator(func):
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs) + f"_d{n}"
                return wrapper
            return decorator

        class TestClass:
            def my_method(self):
                return "original"

        decorated = _multi_decorate([decorator_factory(0), decorator_factory(1), decorator_factory(2)], TestClass.my_method)
        instance = TestClass()
        result = decorated(instance)
        # Order is reversed due to how _multi_decorate applies decorators
        self.assertEqual(result, "original_d2_d1_d0")

    def test_method_decorator_wraps_attribute(self):
        """Test that method_decorator wraps preserve attributes."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.decorator_attr = "value"
            return wrapper

        @method_decorator(my_decorator, name='my_method')
        class TestClass:
            def my_method(self):
                return "original"

        self.assertTrue(hasattr(TestClass.my_method, 'decorator_attr'))
        self.assertEqual(TestClass.my_method.decorator_attr, "value")

