class ModelSignalsClassPreparedTests(SimpleTestCase):
    """Test class_prepared signal."""

    def test_class_prepared_signal_sent(self):
        from django.db.models.base import Model
        from django.db.models.signals import class_prepared

        received_signals = []

        def receiver(sender, **kwargs):
            received_signals.append(sender)

        class TestModel(Model):
            name = models.CharField(max_length=10)

        class_prepared.connect(receiver)
        try:
            # Trigger class preparation
            class AnotherModel(Model):
                age = models.IntegerField()
            self.assertIn(AnotherModel, received_signals)
        finally:
            class_prepared.disconnect(receiver)


