class TestQuerySetInit(SimpleTestCase):
    def test_queryset_init_default(self):
        from django.db.models import Model
        from django.db.models.sql import Query

        class TestModel(Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'bulk_create'

        qs = QuerySet(model=TestModel)
        self.assertEqual(qs.model, TestModel)
        self.assertIsNone(qs._db)
        self.assertIsNotNone(qs._query)
        self.assertIsNone(qs._result_cache)

    def test_queryset_init_with_params(self):
        from django.db.models import Model
        from django.db.models.sql import Query

        class TestModel(Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'bulk_create'

        query = Query(TestModel)
