class TestPrefetch(SimpleTestCase):
    def test_prefetch_init(self):
        prefetch = Prefetch('lookup')
        self.assertEqual(prefetch.prefetch_through, 'lookup')
        self.assertEqual(prefetch.prefetch_to, 'lookup')
        self.assertIsNone(prefetch.queryset)
        self.assertIsNone(prefetch.to_attr)

    def test_prefetch_with_to_attr(self):
        prefetch = Prefetch('parent__child', to_attr='children')
        self.assertEqual(prefetch.prefetch_to, 'parent__children')
        self.assertEqual(prefetch.to_attr, 'children')

    def test_prefetch_eq(self):
        p1 = Prefetch('lookup')
        p2 = Prefetch('lookup')
        self.assertEqual(p1, p2)

    def test_prefetch_hash(self):
        p1 = Prefetch('lookup')
        p2 = Prefetch('lookup')
        self.assertEqual(hash(p1), hash(p2))


