class TestPartitionFunction(SimpleTestCase):
    def test_partition_true_condition(self):
        from django.utils.functional import partition

        items = [1, 2, 3, 4, 5]
        true_items, false_items = partition(lambda x: x > 2, items)
        self.assertEqual(list(true_items), [3, 4, 5])
        self.assertEqual(list(false_items), [1, 2])

    def test_partition_false_condition(self):
        from django.utils.functional import partition

        items = [1, 2, 3, 4, 5]
        true_items, false_items = partition(lambda x: x > 10, items)
        self.assertEqual(list(true_items), [])
        self.assertEqual(list(false_items), [1, 2, 3, 4, 5])


