import signal
from unittest import mock

from django.db.backends.base.client import BaseDatabaseClient
from django.test import SimpleTestCase


class PostgresDbshellCommandTestCase(SimpleTestCase):
    def settings_to_cmd_args_env(self, settings_dict, parameters=None):
        if parameters is None:
            parameters = []
        from django.db.backends.postgresql.client import DatabaseClient
        return DatabaseClient.settings_to_cmd_args_env(settings_dict, parameters)

    def test_basic_settings(self):
        result = self.settings_to_cmd_args_env({"NAME": "mydb"})
        args, env = result
        self.assertEqual(args[0], "psql")
        self.assertIn("mydb", args)

    def test_with_user(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "USER": "admin"
        })
        args, env = result
        self.assertIn("-U", args)
        self.assertIn("admin", args)

    def test_with_host(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "HOST": "localhost"
        })
        args, env = result
        self.assertIn("-h", args)
        self.assertIn("localhost", args)

    def test_with_port(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "PORT": "5432"
        })
        args, env = result
        self.assertIn("-p", args)
        self.assertIn("5432", args)

    def test_with_password(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "PASSWORD": "secret123"
        })
        args, env = result
        self.assertIsNotNone(env)
        self.assertEqual(env["PGPASSWORD"], "secret123")

    def test_with_all_connection_params(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "USER": "admin",
            "HOST": "localhost",
            "PORT": "5432",
            "PASSWORD": "secret"
        })
        args, env = result
        self.assertIn("-U", args)
        self.assertIn("admin", args)
        self.assertIn("-h", args)
        self.assertIn("localhost", args)
        self.assertIn("-p", args)
        self.assertIn("5432", args)
        self.assertEqual(env["PGPASSWORD"], "secret")

    def test_default_database_when_no_name_or_service(self):
        result = self.settings_to_cmd_args_env({})
        args, env = result
        self.assertIn("postgres", args)

    def test_parameters_are_appended(self):
        result = self.settings_to_cmd_args_env(
            {"NAME": "mydb"},
            ["-f", "script.sql"]
        )
        args, env = result
        self.assertIn("-f", args)
        self.assertIn("script.sql", args)

    def test_options_passfile(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "OPTIONS": {"passfile": "/path/to/passfile"}
        })
        args, env = result
        self.assertEqual(env["PGPASSFILE"], "/path/to/passfile")

    def test_options_service(self):
