    def test_runshell_sigint_handler_restored(self):
        from django.db.backends.postgresql.client import DatabaseClient

        mock_connection = mock.Mock()
        mock_connection.settings_dict = {
            "NAME": "mydb",
            "USER": "admin",
            "HOST": "localhost",
            "PORT": "5432",
            "PASSWORD": "secret"
        }

        client = DatabaseClient(mock_connection)

        original_handler = signal.SIG_IGN
        with mock.patch('signal.getsignal', return_value=original_handler):
            with mock.patch('signal.signal') as mock_signal:
                with mock.patch.object(BaseDatabaseClient, 'runshell'):
                    client.runshell([])

                    # Should call signal.signal twice - once to ignore, once to restore
                    calls = mock_signal.call_args_list
                    self.assertEqual(len(calls), 2)
                    # First call should set SIGINT to SIG_IGN
                    self.assertEqual(calls[0][0][1], signal.SIG_IGN)
                    # Second call should restore original handler
                    self.assertEqual(calls[1][0][1], original_handler)

    def test_runshell_super_called_with_parameters(self):
        from django.db.backends.postgresql.client import DatabaseClient
        from django.db.backends.base.client import BaseDatabaseClient

        mock_connection = mock.Mock()
        mock_connection.settings_dict = {"NAME": "mydb"}

        client = DatabaseClient(mock_connection)

        with mock.patch('signal.getsignal', return_value=signal.SIG_DFL):
            with mock.patch('signal.signal'):
                with mock.patch.object(BaseDatabaseClient, 'runshell') as mock_super:
                    mock_super.return_value = None
                    client.runshell(["-f", "test.sql"])
                    # Verify super().runshell was called with parameters
                    mock_super.assert_called_once_with(["-f", "test.sql"])

    def test_executable_name_is_psql(self):
        from django.db.backends.postgresql.client import DatabaseClient
        self.assertEqual(DatabaseClient.executable_name, "psql")

    def test_settings_to_cmd_args_env_classmethod(self):
        from django.db.backends.postgresql.client import DatabaseClient

        result = DatabaseClient.settings_to_cmd_args_env(
            {"NAME": "testdb"},
            ["--single-transaction"]
        )
        args, env = result
        self.assertIsInstance(args, list)
        self.assertIsInstance(env, (dict, type(None)))

    def test_multiple_ssl_options(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "OPTIONS": {
                "sslmode": "verify-full",
                "sslrootcert": "/root.crt",
                "sslcert": "/client.crt",
                "sslkey": "/client.key"
            }
        })
        args, env = result
        self.assertEqual(env["PGSSLMODE"], "verify-full")
        self.assertEqual(env["PGSSLROOTCERT"], "/root.crt")
        self.assertEqual(env["PGSSLCERT"], "/client.crt")
        self.assertEqual(env["PGSSLKEY"], "/client.key")

    def test_password_as_string_in_env(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "PASSWORD": 12345
        })
        args, env = result
        self.assertEqual(env["PGPASSWORD"], "12345")

    def test_port_as_integer(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "PORT": 5432
        })
        args, env = result
        self.assertIn("5432", args)

    def test_empty_options_dict(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "OPTIONS": {}
        })
        args, env = result
        self.assertIsNone(env)

    def test_no_dbname_but_with_service(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "",
            "OPTIONS": {"service": "django"}
        })
        args, env = result
        self.assertEqual(env["PGSERVICE"], "django")
        # Should not add default postgres db when service is present

    def test_order_of_args(self):
        result = self.settings_to_cmd_args_env({
            "NAME": "mydb",
            "USER": "admin",
            "HOST": "localhost",
            "PORT": "5432"
        }, ["-c", "SELECT 1"])
        args, env = result
        # Check order: psql, -U user, -h host, -p port, parameters, dbname
        expected_order = ["psql", "-U", "admin", "-h", "localhost", "-p", "5432", "-c", "SELECT 1", "mydb"]
        self.assertEqual(args, expected_order)

