from django.test import SimpleTestCase


class TestManagementForm(SimpleTestCase):
    """Tests for ManagementForm class."""

    def test_management_form_init(self):
        from django.forms.formsets import ManagementForm, TOTAL_FORM_COUNT, INITIAL_FORM_COUNT
        form = ManagementForm()
        self.assertIn(TOTAL_FORM_COUNT, form.base_fields)
        self.assertIn(INITIAL_FORM_COUNT, form.base_fields)

    def test_management_form_clean_with_data(self):
        from django.forms.formsets import ManagementForm, TOTAL_FORM_COUNT, INITIAL_FORM_COUNT
        data = {
            'TOTAL_FORMS': '2',
            'INITIAL_FORMS': '1',
        }
