from django.template.defaultfilters import join
from django.test import SimpleTestCase
from django.utils.safestring import mark_safe, SafeString

from ..utils import setup


class JoinTests(SimpleTestCase):
    @setup({"join01": "{{ a|join:', ' }} {{ b|join:', ' }}"})
    def test_join01(self):
        output = self.engine.render_to_string(
            "join01", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), mark_safe("x")]}
        )
        self.assertEqual(output, "a&amp;b, x a&b, x")

    @setup(
        {
            "join02": (
                "{% autoescape off %}{{ a|join:', ' }} {{ b|join:', ' }}{% endautoescape %}"
            )
        }
    )
    def test_join02(self):
        output = self.engine.render_to_string(
            "join02", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), mark_safe("x")]}
        )
        self.assertEqual(output, "a&b, x a&b, x")

    @setup({"join03": '{{ a|join:"-" }}'})
    def test_join03(self):
        output = self.engine.render_to_string("join03", {"a": ["hello", "world"]})
        self.assertEqual(output, "hello-world")

    @setup({"join04": '{{ a|join:"" }}'})
    def test_join04(self):
        output = self.engine.render_to_string("join04", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "abc")

    @setup({"join05": '{{ a|join:", " }}'})
    def test_join05(self):
        output = self.engine.render_to_string("join05", {"a": []})
        self.assertEqual(output, "")

    @setup({"join06": '{{ a|join:"|" }}'})
    def test_join06(self):
        output = self.engine.render_to_string("join06", {"a": ["single"]})
        self.assertEqual(output, "single")

    @setup({"join07": '{{ a|join:" " }} {{ b|join:" " }}'})
    def test_join07(self):
        output = self.engine.render_to_string(
            "join07",
            {
                "a": ["<script>alert('xss')</script>", "safe"],
                "b": [mark_safe("<script>alert('xss')</script>"), mark_safe("safe")],
            },
        )
        self.assertEqual(output, "&lt;script&gt;alert(&#x27;xss&#x27;)&lt;/script&gt;, safe <script>alert('xss')</script>, safe")

    @setup({"join08": '{% autoescape off %}{{ a|join:"|" }}{% endautoescape %}'})
    def test_join08(self):
        output = self.engine.render_to_string(
            "join08", {"a": ["<script>x</script>", "y"]}
        )
        self.assertEqual(output, "<script>x</script>|y")

    @setup({"join09": '{{ a|join:"<br>" }}'})
    def test_join09(self):
        output = self.engine.render_to_string("join09", {"a": ["line1", "line2"]})
        self.assertEqual(output, "line1<br>line2")

    @setup({"join10": '{{ a|join:"\\n" }}'})
    def test_join10(self):
        output = self.engine.render_to_string("join10", {"a": ["line1", "line2"]})
        self.assertEqual(output, "line1\nline2")


class FunctionTests(SimpleTestCase):
    def test_basic_join(self):
        result = join(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_empty_list(self):
        result = join([], ", ")
        self.assertEqual(result, "")

    def test_single_item(self):
        result = join(["only"], ", ")
        self.assertEqual(result, "only")

    def test_with_numbers(self):
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_with_mixed_types(self):
        result = join([1, "two", 3.0], " + ")
        self.assertEqual(result, "1 + two + 3.0")

    def test_with_none_values(self):
        result = join([None, "value", None], "|")
        self.assertEqual(result, "None|value|None")

    def test_with_special_characters(self):
        result = join(["a&b", "c<d"], ">")
        self.assertEqual(result, "a&amp;b>c&lt;d")

    def test_with_unicode(self):
        result = join(["héllo", "wörld"], " ")
        self.assertEqual(result, "héllo wörld")

    def test_with_html_tags(self):
        result = join(["<b>bold</b>", "<i>italic</i>"], " | ")
        self.assertIn("&lt;b&gt;", result)

    def test_with_safe_string_input(self):
        safe_val = mark_safe("safe & value")
        result = join([safe_val, "other"], ", ")
        self.assertIn("safe & value", result)

    def test_with_empty_separator(self):
        result = join(["a", "b", "c"], "")
        self.assertEqual(result, "abc")

    def test_with_newline_separator(self):
        result = join(["line1", "line2", "line3"], "\n")
        self.assertEqual(result, "line1\nline2\nline3")

    def test_with_tab_separator(self):
        result = join(["col1", "col2"], "\t")
        self.assertEqual(result, "col1\tcol2")

    def test_with_long_separator(self):
        result = join(["a", "b"], "separator")
        self.assertEqual(result, "aseparatorb")

    def test_with_boolean_values(self):
        result = join([True, False, True], " | ")
        self.assertEqual(result, "True | False | True")

    def test_with_zero_values(self):
        result = join([0, 0, 0], "+")
        self.assertEqual(result, "0+0+0")

    def test_with_float_values(self):
        result = join([1.5, 2.5, 3.5], " - ")
        self.assertEqual(result, "1.5 - 2.5 - 3.5")

    def test_fails_silently_on_non_iterable_arg(self):
        class NonIterable:
            pass
        obj = NonIterable()
        result = join(["a", "b"], obj)
        # Returns original value when arg isn't iterable
        self.assertEqual(result, ["a", "b"])

    def test_fails_silently_on_invalid_value_type(self):
        result = join(None, ", ")
        self.assertEqual(result, None)

    def test_autoescape_false(self):
        result = join(["a&b", "c<d"], ", ", autoescape=False)
        self.assertEqual(result, "a&b, c<d")

    def test_autoescape_true_default(self):
        result = join(["a&b", "c<d"], ", ", autoescape=True)
        self.assertIn("&amp;", result)

    def test_with_safe_data_object(self):
        from django.utils.safestring import SafeData

        class CustomSafe(SafeData):
            def __init__(self, value):
                self.value = value

            def __str__(self):
                return self.value

        safe_obj = CustomSafe("safe & data")
        result = join([safe_obj, "unsafe"], "|")
        self.assertIn("safe & data", result)

    def test_with_generator(self):
        def gen():
            yield "a"
            yield "b"
            yield "c"
        result = join(gen(), "-")
        self.assertEqual(result, "a-b-c")

    def test_with_tuple(self):
        result = join(("x", "y", "z"), ":")
        self.assertEqual(result, "x:y:z")

    def test_with_set(self):
        # Sets are unordered, so we just check it works
        result = join({1, 2, 3}, ",")
        self.assertIsInstance(result, str)
        self.assertIn("1", result)
        self.assertIn("2", result)
        self.assertIn("3", result)

    def test_with_bytes_like(self):
        result = join([b"a", b"b"], b"-")
        self.assertEqual(result, b"a-b")

    def test_with_empty_strings(self):
        result = join(["", "", ""], "|")
        self.assertEqual(result, "||")

    def test_with_whitespace_only(self):
        result = join(["   ", "\t", "\n"], "|")
        self.assertEqual(result, "   |\t|\n")

    def test_with_numeric_strings(self):
        result = join(["1", "2", "3"], "+")
        self.assertEqual(result, "1+2+3")

    def test_with_large_list(self):
        large_list = list(range(100))
        result = join(large_list, ",")
        expected = ",".join(str(i) for i in range(100))
        self.assertEqual(result, expected)

    def test_with_django_safe_string(self):
        safe_str = mark_safe("already & escaped")
        result = join([safe_str, "normal"], " | ")
        self.assertIn("already & escaped", result)

    def test_with_nested_lists(self):
        result = join([["nested"], ["list"]], ",")
        self.assertEqual(result, "['nested'],['list']")

    def test_with_dict_values(self):
        d = {"a": 1, "b": 2}
        result = join(d.values(), ",")
        self.assertIn("1", result)
        self.assertIn("2", result)

    def test_with_custom_class_objects(self):
        class CustomObj:
            def __str__(self):
                return "custom"

        result = join([CustomObj(), CustomObj()], " + ")
        self.assertEqual(result, "custom + custom")

    def test_with_exception_raising_str(self):
        class BadStr:
            def __str__(self):
                raise ValueError("bad string")

        try:
            result = join([BadStr()], ",")
            # Should handle gracefully
        except Exception:
            pass  # Accept if it raises

