class TestModelChoiceFieldInit(SimpleTestCase):
    def test_basic_init(self):
        from django.db import models
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs)
        self.assertEqual(field.queryset, qs)
        self.assertIsNone(field.empty_label)

    def test_with_empty_label_none(self):
        from django.db import models
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs, empty_label=None)
        self.assertIsNone(field.empty_label)

    def test_with_empty_label_default(self):
        from django.db import models
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs)
        self.assertEqual(field.empty_label, "---------")

    def test_required_true_initial_none(self):
        from django.db import models
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs, required=True, initial=None)
        self.assertIsNone(field.empty_label)

    def test_required_false_initial_none(self):
        from django.db import models
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs, required=False, initial=None)
        self.assertEqual(field.empty_label, "---------")

    def test_radio_select_not_blank(self):
        from django.db import models
        from django.forms.widgets import RadioSelect
        qs = Category.objects.all()
        field = ModelChoiceField(queryset=qs, widget=RadioSelect(), blank=False)
        self.assertIsNone(field.empty_label)

    def test_limit_choices_to_callable(self):
        from django.db import models
        qs = Category.objects.all()

        def limit_func():
            return {'name': 'test'}

        field = ModelChoiceField(queryset=qs, limit_choices_to=limit_func)
        result = field.get_limit_choices_to()
        self.assertEqual(result, {'name': 'test'})

    def test_limit_choices_to_q_object(self):
        from django.db import models
        from django.db.models import Q
        qs = Category.objects.all()

        q_obj = Q(name='test')
        field = ModelChoiceField(queryset=qs, limit_choices_to=q_obj)
        result = field.get_limit_choices_to()
        self.assertEqual(result, q_obj)


class TestModelChoiceFieldToPython(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.c1 = Category.objects.create(name='Cat1', slug='cat1')
        cls.c2 = Category.objects.create(name='Cat2', slug='cat2')

    def test_valid_pk(self):
        field = ModelChoiceField(Category.objects.all())
        result = field.to_python(self.c1.pk)
        self.assertEqual(result, self.c1)

    def test_valid_string_pk(self):
        field = ModelChoiceField(Category.objects.all())
        result = field.to_python(str(self.c1.pk))
        self.assertEqual(result, self.c1)

    def test_invalid_pk_value_error(self):
        field = ModelChoiceField(Category.objects.all())
        with self.assertRaises(ValidationError):
            field.to_python('invalid')

