    def test_refs_expression_match(self):
        from django.db.models.query_utils import refs_expression
        annotations = {'my_annotation': 'annotation_value'}
        result, remaining = refs_expression(['my_annotation', 'lookup'], annotations)
        self.assertIsNotNone(result)
        self.assertEqual(remaining, ['lookup'])

    def test_refs_expression_no_match(self):
        from django.db.models.query_utils import refs_expression
        annotations = {'other_annotation': 'annotation_value'}
        result, remaining = refs_expression(['my_annotation', 'lookup'], annotations)
        self.assertFalse(result)
        self.assertEqual(remaining, ())


