class TestFilteredRelationInit(SimpleTestCase):
    """Tests for FilteredRelation class __init__ method."""

    def test_filtered_relation_init_valid(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr = FilteredRelation('relation_name', condition=Q())
        self.assertEqual(fr.relation_name, 'relation_name')
        self.assertEqual(fr.alias, None)
        self.assertEqual(fr.path, [])

    def test_filtered_relation_init_empty_relation_name_raises(self):
        from django.db.models.query_utils import FilteredRelation, Q
        with self.assertRaises(ValueError) as context:
            FilteredRelation('', condition=Q())
        self.assertIn('relation_name cannot be empty', str(context.exception))

    def test_filtered_relation_init_invalid_condition_raises(self):
        from django.db.models.query_utils import FilteredRelation
        with self.assertRaises(ValueError) as context:
            FilteredRelation('relation_name', condition='not a Q')
        self.assertIn('condition argument must be a Q() instance', str(context.exception))


class TestFilteredRelationEq(SimpleTestCase):
    """Tests for FilteredRelation class __eq__ method."""

    def test_eq_same_values(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr1 = FilteredRelation('relation_name', condition=Q())
        fr2 = FilteredRelation('relation_name', condition=Q())
        self.assertEqual(fr1, fr2)

    def test_eq_different_relation_name(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr1 = FilteredRelation('relation_name1', condition=Q())
        fr2 = FilteredRelation('relation_name2', condition=Q())
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_condition(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr1 = FilteredRelation('relation_name', condition=Q(field1='value1'))
        fr2 = FilteredRelation('relation_name', condition=Q(field2='value2'))
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_type(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr1 = FilteredRelation('relation_name', condition=Q())
        fr2 = 'not a FilteredRelation'
        self.assertNotEqual(fr1, fr2)


class TestFilteredRelationClone(SimpleTestCase):
    """Tests for FilteredRelation class clone method."""

    def test_clone(self):
        from django.db.models.query_utils import FilteredRelation, Q
        fr = FilteredRelation('relation_name', condition=Q(field1='value1'))
        fr.alias = 'test_alias'
        fr.path = ['path1', 'path2']

        cloned = fr.clone()
        self.assertEqual(cloned.relation_name, 'relation_name')
        self.assertEqual(cloned.alias, 'test_alias')
        self.assertEqual(cloned.path, ['path1', 'path2'])


