)


class TestManagementForm(SimpleTestCase):
    def test_management_form_fields(self):
        from django.forms.formsets import ManagementForm

        form = ManagementForm()
        self.assertIn("TOTAL_FORMS", form.fields)
        self.assertIn("INITIAL_FORMS", form.fields)
        self.assertIn("MIN_NUM_FORMS", form.fields)
        self.assertIn("MAX_NUM_FORMS", form.fields)

    def test_management_form_widget_types(self):
        from django.forms.formsets import ManagementForm
        from django.forms.widgets import HiddenInput

        form = ManagementForm()
        self.assertIsInstance(form.fields["TOTAL_FORMS"].widget, HiddenInput)
        self.assertIsInstance(form.fields["INITIAL_FORMS"].widget, HiddenInput)
        self.assertIsInstance(form.fields["MIN_NUM_FORMS"].widget, HiddenInput)
        self.assertIsInstance(form.fields["MAX_NUM_FORMS"].widget, HiddenInput)

    def test_management_form_clean_defaults(self):
        from django.forms.formsets import ManagementForm, TOTAL_FORM_COUNT, INITIAL_FORM_COUNT

        # Empty data should default to 0
        form = ManagementForm(data={})
        form.full_clean()
        self.assertEqual(form.cleaned_data.get(TOTAL_FORM_COUNT), 0)
        self.assertEqual(form.cleaned_data.get(INITIAL_FORM_COUNT), 0)

    def test_management_form_with_data(self):
        from django.forms.formsets import ManagementForm, TOTAL_FORM_COUNT

        data = {
            "TOTAL_FORMS": "5",
            "INITIAL_FORMS": "2",
        }
        form = ManagementForm(data=data)
        self.assertTrue(form.is_valid())
        self.assertEqual(form.cleaned_data[TOTAL_FORM_COUNT], 5)


