class TestBaseFormSetCleanedData(SimpleTestCase):
    def test_cleaned_data_valid(self):
        from django.forms.formsets import BaseFormSet

        class TestFormSet(BaseFormSet):
            form = SampleForm
            extra = 1

        data = {
            "form-TOTAL_FORMS": "1",
