class TestBaseFormSetCustomFormSetSubclass(SimpleTestCase):
    def test_custom_formset_subclass(self):
        from django.forms.formsets import BaseFormSet

        class CustomFormSet(BaseFormSet):
            form = SampleForm

            def clean(self):
                super().clean()
                if len(self.forms) > 5:
                    raise ValidationError("Too many forms!")

        data = {
            "form-TOTAL_FORMS": "1",
            "form-INITIAL_FORMS": "0",
            "form-0-name": "Alice",
        }
        formset = CustomFormSet(data=data)
        self.assertTrue(formset.is_valid())

        data = {
            "form-TOTAL_FORMS": "6",
            "form-INITIAL_FORMS": "0",
            "form-0-name": "Alice",
            "form-1-name": "Bob",
            "form-2-name": "Charlie",
            "form-3-name": "David",
            "form-4-name": "Eve",
            "form-5-name": "Frank",
        }
        formset = CustomFormSet(data=data)
        self.assertFalse(formset.is_valid())
        self.assertEqual(len(formset._non_form_errors), 1)

"""Tests for django.dispatch.dispatcher module."""

import threading
import weakref
from unittest import mock

from django.test import SimpleTestCase, override_settings
from django.utils.deprecation import RemovedInDjango40Warning


class SignalInitializationTests(SimpleTestCase):
    """Test Signal class initialization."""

    def test_signal_init_default(self):
        from django.dispatch import Signal
        signal = Signal()
        self.assertEqual(signal.receivers, [])
        self.assertFalse(signal.use_caching)
        self.assertIsInstance(signal.lock, type(threading.Lock()))
        self.assertEqual(signal.sender_receivers_cache, {})
        self.assertFalse(signal._dead_receivers)

    def test_signal_init_with_providing_args_deprecated(self):
        from django.dispatch import Signal
        with self.assertWarns(RemovedInDjango40Warning):
            signal = Signal(providing_args=['arg1', 'arg2'])
        self.assertEqual(signal.receivers, [])

    def test_signal_init_with_use_caching(self):
        from django.dispatch import Signal
        signal = Signal(use_caching=True)
        self.assertTrue(signal.use_caching)
        self.assertIsNotNone(signal.sender_receivers_cache)

    def test_signal_init_empty_caches(self):
        from django.dispatch import Signal
        # Even without use_caching, empty caches are created for convenience
        signal = Signal()
        self.assertEqual(signal.sender_receivers_cache, {})


