class IntegrationTests(SimpleTestCase):
    """Integration tests for Signal functionality."""

    def test_full_lifecycle(self):
        from django.dispatch import Signal

        signal = Signal()
        events = []

        def handler1(sender, **kwargs):
            events.append(('handler1', kwargs))

        def handler2(sender, **kwargs):
            events.append(('handler2', kwargs))

        # Connect handlers
        signal.connect(handler1)
        signal.connect(handler2, dispatch_uid='h2')

        # Send signal
        signal.send('sender', data=42)

        # Verify both handlers were called
        self.assertEqual(len(events), 2)

        # Disconnect one handler
        signal.disconnect(dispatch_uid='h2')

        # Send again
        events.clear()
        signal.send('sender', data=99)

        # Only handler1 should have been called
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0][0], 'handler1')

    def test_receiver_accepts_signal_parameter(self):
        from django.dispatch import Signal

        signal = Signal()
        received_signal = []

        def handler(sender, **kwargs):
            received_signal.append(kwargs.get('signal'))

        signal.connect(handler)
        signal.send('sender')

        self.assertEqual(len(received_signal), 1)
        self.assertIs(received_signal[0], signal)
